ого байта кода номер e в дереве        OR (HL)        DEC HL        LD L,(HL)        LD H,A        JP M,_ZD58C ;hl>=0x8000 значит дерево, иначе l=литерал         PUSH HL         LD DE,TD61A ;длины кодов первого дерева         ADD HL,DE         LD A,(HL) ;длина кода для имеющегося e         POP HL,DE_ZD560  CALL read_a_bits        LD A,H        OR A        RET Z        LD A,L        CP 9        RET C        CP #1D        LD HL,#200        RET Z        DEC A        LD C,A        SRL C        SRL C        DEC C        AND 3        ADD A,4        LD H,L        LD L,A        LD A,CZD57E   ADD HL,HL        DEC C        JR NZ,ZD57E        INC H        CALL get_a_bits        INC A        ADD A,L        LD L,A        RET NC        INC H        RET _ZD58C  POP DE        CALL ZD5CB ;читать 8 бит и пройти по ним дерево hl        JR _ZD560readcodetree2;ZD592;de=имеющиеся данные;out: hl=code;The distance tree contains space for 32 symbols:;0–3: distances 1–4;4–5: distances 5–8, 1 extra bit;6–7: distances 9–16, 2 extra bits;8–9: distances 17–32, 3 extra bits;...;26–27: distances 8,193–16,384, 12 extra bits;28–29: distances 16,385–32,768, 13 extra bits;30–31: not used, reserved and illegal but still part of the tree.;Note that for the match distance symbols 2–29, the number of extra bits can be calculated as [n/2]-1.        PUSH DE        XOR A        LD D,A        LD HL,TD61A+#360+1        ADD HL,DE        ADD HL,DE        OR (HL)        DEC HL        LD L,(HL)        LD H,A ;hl>=0x8000 значит дерево, иначе l=литерал        JP M,_ZD5C5 ;читать 8 бит и пройти по ним дерево hl         PUSH HL         LD DE,TD61A+#140 ;длины кодов второго дерева         ADD HL,DE         LD A,(HL) ;длина кода для имеющегося e         POP HL,DE_ZD5A9  CALL read_a_bits ;дочитываем столько бит, сколько прошагали?        LD A,L ;литерал        CP 4        RET C        RRA         DEC A        LD C,A        LD L,H        RL L        INC L,LZD5B8   ADD HL,HL        DEC C        JR NZ,ZD5B8        PUSH HL        CALL get_a_bits_tohl        EX DE,HL        EX (SP),HL        ADD HL,DE        POP DE        RET _ZD5C5   POP DE        CALL ZD5CB ;читать 8 бит и пройти по ним дерево hl        JR _ZD5A9ZD5CB;читать 8 бит и пройти по ним дерево hl;out: a=сколько бит реально прошагали, l=литерал?        LD A,8        CALL read_a_bits        LD C,E ;эквивалентно ld a,8:call get_a_bits:ld c,a ?;ходим по дереву hl, имея код C (младшие биты сначала)        XOR AZD5D2   INC A        RR C        JR NC,ZD5D9        INC HL,HLZD5D9   LD (ZD5DD),HLZD5DD=$+1        LD HL,(0)        BIT 7,H ;hl>=0x8000 значит дерево, иначе l=литерал        JR NZ,ZD5D2        RET TD61A=0x8000 ;чтобы было >=0x8000
